#include "encryption.h"
#include "access_control.h"
#include "audit_log.h"
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <fstream>
#include <sstream>
#include <iomanip>
namespace secureos { static std::string toHex(const unsigned char*p,size_t n){std::ostringstream o;for(size_t i=0;i<n;i++)o<<std::hex<<std::setw(2)<<std::setfill('0')<<(int)p[i];return o.str();} static bool fromHex(const std::string&s,unsigned char*out,size_t n){if(s.size()!=2*n)return false;for(size_t i=0;i<n;i++){unsigned int v;std::istringstream x(s.substr(i*2,2));if(!(x>>std::hex>>v))return false;out[i]=(unsigned char)v;}return true;}
EncryptionService::EncryptionService(std::filesystem::path d,AuditLog&a):root(std::move(d)/"files"),log(a){}
static bool safe(const std::filesystem::path&r,const std::string&n){return isSafeName(n)&&std::filesystem::exists(r/n);}
bool EncryptionService::encrypt(const User&u,const std::string&in,const std::string&out,std::string&key,std::string&m){if(!allowed(u.role,Action::Encrypt)||!safe(root,in)||!isSafeName(out)){m="Access denied or unsafe/missing filename.";log.record(u.name,"denied encryption");return false;}if(std::filesystem::exists(root/out)){m="Output already exists; choose another name.";return false;}std::ifstream f(root/in,std::ios::binary);std::vector<unsigned char>plain((std::istreambuf_iterator<char>(f)),{}),cipher(plain.size()+16),k(32),nonce(12),tag(16);if(RAND_bytes(k.data(),32)!=1||RAND_bytes(nonce.data(),12)!=1){m="Random generator failed.";return false;}EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();int l=0,total=0;bool ok=c&&EVP_EncryptInit_ex(c,EVP_aes_256_gcm(),nullptr,k.data(),nonce.data())&&EVP_EncryptUpdate(c,cipher.data(),&l,plain.data(),(int)plain.size());total=l;ok=ok&&EVP_EncryptFinal_ex(c,cipher.data()+total,&l)&&EVP_CIPHER_CTX_ctrl(c,EVP_CTRL_GCM_GET_TAG,16,tag.data());total+=l;EVP_CIPHER_CTX_free(c);if(!ok){m="Encryption failed.";return false;}std::ofstream o(root/out,std::ios::binary);o.write("SOS1",4);o.write((char*)nonce.data(),12);o.write((char*)tag.data(),16);o.write((char*)cipher.data(),total);if(!o){std::filesystem::remove(root/out);m="Output write failed.";return false;}key=toHex(k.data(),k.size());log.record(u.name,"encrypted "+in+" to "+out);m="Encrypted. Save the displayed key outside this application.";return true;}
bool EncryptionService::decrypt(const User&u,const std::string&in,const std::string&out,const std::string&key,std::string&m){if(!allowed(u.role,Action::Decrypt)||!safe(root,in)||!isSafeName(out)){m="Access denied or unsafe/missing filename.";log.record(u.name,"denied decryption");return false;}if(std::filesystem::exists(root/out)){m="Output already exists; choose another name.";return false;}unsigned char k[32];if(!fromHex(key,k,32)){m="Key must be 64 hexadecimal characters.";return false;}std::ifstream f(root/in,std::ios::binary);char magic[4];unsigned char nonce[12],tag[16];f.read(magic,4);f.read((char*)nonce,12);f.read((char*)tag,16);if(!f||std::string(magic,4)!="SOS1"){m="Not a SecureOS encrypted file.";return false;}std::vector<unsigned char>cipher((std::istreambuf_iterator<char>(f)),{}),plain(cipher.size()+16);EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();int l=0,total=0;bool ok=c&&EVP_DecryptInit_ex(c,EVP_aes_256_gcm(),nullptr,k,nonce)&&EVP_DecryptUpdate(c,plain.data(),&l,cipher.data(),(int)cipher.size());total=l;ok=ok&&EVP_CIPHER_CTX_ctrl(c,EVP_CTRL_GCM_SET_TAG,16,tag)&&EVP_DecryptFinal_ex(c,plain.data()+total,&l);total+=l;EVP_CIPHER_CTX_free(c);if(!ok){m="Decryption failed: wrong key or tampered ciphertext.";return false;}std::ofstream o(root/out,std::ios::binary);o.write((char*)plain.data(),total);if(!o){std::filesystem::remove(root/out);m="Output write failed.";return false;}log.record(u.name,"decrypted "+in+" to "+out);m="Decryption successful.";return true;}
}
